import{a as e,i as t,r as n,t as r}from"./app-DllFuXBm.js";var i=JSON.parse(`{"path":"/guide/profile.html","title":"资料与头像","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1791121863000,"contributors":[{"name":"ShiroMizu","username":"","email":"ShiroMizuTan@163.com","commits":1}],"changelog":[{"hash":"166a3aafef6a84f2d36cd610c59ea02e9855f9e0","time":1791121863000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add profile/avatar and message management pages"}]},"filePathRelative":"guide/profile.md"}`),a={name:`profile.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="资料与头像" tabindex="-1"><a class="header-anchor" href="#资料与头像"><span>资料与头像</span></a></h1><h2 id="查看资料" tabindex="-1"><a class="header-anchor" href="#查看资料"><span>查看资料</span></a></h2><table><thead><tr><th>指令</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>我的信息</code></td><td><code>.我的信息</code></td><td>查看自己的资料卡</td></tr></tbody></table><p>资料卡里包含你的昵称、等级、经验、升级进度、金币和头像。</p><h2 id="设置头像" tabindex="-1"><a class="header-anchor" href="#设置头像"><span>设置头像</span></a></h2><table><thead><tr><th>指令</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>设置头像</code> / <code>换头像</code> / <code>改头像</code></td><td>见下方说明</td><td>把一张图片设为自己的头像</td></tr><tr><td><code>恢复头像</code> / <code>默认头像</code> / <code>还原头像</code></td><td><code>.恢复头像</code></td><td>恢复成默认头像</td></tr><tr><td><code>我的头像</code> / <code>查看头像</code> / <code>头像</code></td><td><code>.我的头像</code></td><td>单独发送自己现在的头像</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">怎么设置头像</p><p><strong>在一张图片上回复这条指令</strong>，也就是说：</p><ol><li>先发一张图片</li><li>在这条图片消息上回复 <code>.设置头像</code></li></ol><p>不能空发 <code>.设置头像</code>，那样没有图片可用。</p></div><h2 id="头像的几种状态" tabindex="-1"><a class="header-anchor" href="#头像的几种状态"><span>头像的几种状态</span></a></h2><table><thead><tr><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>默认头像</td><td>刚使用时的状态，显示你的 QQ 头像</td></tr><tr><td>自己设的头像</td><td>用 <code>.设置头像</code> 换过之后，就一直显示这张</td></tr><tr><td>恢复默认</td><td>用 <code>.恢复头像</code> 退回默认状态</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">换 QQ 也不影响</p><p>自己设的头像保存在服务器上，跟你的账号走，不依赖 QQ 号。</p></div><h2 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题"><span>常见问题</span></a></h2><p><strong>Q：图片要多大？</strong> 有大小限制，太大的图片会被拒绝，换一张小一点的就行。</p><p><strong>Q：为什么设不了头像？</strong> 检查一下是不是没有在图片消息上回复，而是单独发了一条指令。</p><p><strong>Q：我的头像会出现在哪里？</strong> 资料卡上会显示你设置的头像。舞萌的 Best 50 / AP 50 卡片上也会显示玩家的头像。</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};